import { getDecoratedNavPageAndSlug, InvalidEndpointFrontmatterError, parseFrontmatter, } from '@mintlify/common';
import { promises as _promises } from 'fs';
import { join } from 'path';
import { createGeneratedGraphqlRouteIndex, preserveAutoGeneratedMetadata, } from '../preserveAutoGeneratedMetadata.js';
